MANUFACTURERS = tuple(sorted(SENSORS, key=str.casefold))


def sensors_for(manufacturer):
    """Return the model names available for a manufacturer."""
    return tuple(sorted(SENSORS.get(manufacturer, {}), key=str.casefold))


def sensor(manufacturer, model):
    """Return the database entry for a manufacturer/model pair."""
    return SENSORS.get(manufacturer, {}).get(model)


def default_manufacturer():
    """Return the preferred initial manufacturer."""
    if "Sony" in SENSORS:
        return "Sony"
    return MANUFACTURERS[0] if MANUFACTURERS else ""


def default_model(manufacturer):
    """Return the preferred initial model for a manufacturer."""
    models = sensors_for(manufacturer)
    if "IMX174" in models:
        return "IMX174"
    return models[0] if models else ""


COMMON_ASPECT_RATIOS = ((1, 1), (4, 3), (16, 9), (16, 10), (14, 9))
ASPECT_RATIO_TOLERANCE = 0.02


def _format_number(value):
    text = f"{value:.2f}".rstrip("0").rstrip(".")
    return text or "0"


def aspect_ratio_label(resolution):
    """Return a common aspect-ratio label, or a numeric width:height label."""
    width, height = resolution
    if height <= 0:
        return ""
    ratio = float(width) / float(height)
    for common_width, common_height in COMMON_ASPECT_RATIOS:
        target = common_width / common_height
        if abs(ratio - target) <= ASPECT_RATIO_TOLERANCE * target:
            return f"{common_width}:{common_height}"
        inverse = 1.0 / target
        if abs(ratio - inverse) <= ASPECT_RATIO_TOLERANCE * target:
            return f"{common_height}:{common_width}"
    if ratio < 1.0:
        return f"1:{_format_number(1.0 / ratio)}"
    return f"{_format_number(ratio)}:1"


def sensor_label(manufacturer, model):
    """Return the model name followed by resolution and aspect ratio."""
    entry = sensor(manufacturer, model)
    if entry is None:
        return model
    resolution = entry["resolution"]
    ratio = aspect_ratio_label(resolution)
    return f"{model} ({resolution[0]}, {resolution[1]}) {ratio}"
